for coin, content in raw_data.items():
    for group_type in ['heads_groups', 'tails_groups']:
        for i, sublist in enumerate(content[group_type]):
            if len(sublist) != 100:
                print(f" {coin} {group_type} group {i} has {len(sublist)} elements (should be 100)")

# --- 3. INDIVIDUAL COIN PLOTS ---
for coin_type, data in raw_data.items():
    # Flatten groups for this specific coin
    h_list = [item for sublist in data["heads_groups"] for item in sublist]
    t_list = [item for sublist in data["tails_groups"] for item in sublist]
    
    h_path = np.cumsum(h_list)
    t_path = np.cumsum(t_list)
    
    plt.figure(figsize=(12, 6))
    plt.plot(h_path, label=f'Heads Total: {h_path[-1]}', color='blue', linewidth=2)
    plt.plot(t_path, label=f'Tails Total: {t_path[-1]}', color='green', linewidth=2)
    
    plt.title(f'Cumulative Coin Toss Results: {coin_type}')
    plt.xlabel('Number of Tosses')
    plt.ylabel('Cumulative Count')
    plt.legend()
    plt.grid(True)
    plt.show()

# --- 2. AGGREGATED GLOBAL PLOT ---
# Aggregate all heads and tails across every coin type in the dictionary
all_heads_global = []
all_tails_global = []
for coin, data in raw_data.items():
    all_heads_global.extend([item for sublist in data["heads_groups"] for item in sublist])
    all_tails_global.extend([item for sublist in data["tails_groups"] for item in sublist])

heads_cum_global = np.cumsum(all_heads_global)
tails_cum_global = np.cumsum(all_tails_global)

plt.figure(figsize=(12, 6))
plt.plot(heads_cum_global, label=f'All Heads Total: {heads_cum_global[-1]}', color='blue', linewidth=2)
plt.plot(tails_cum_global, label=f'All Tails Total: {tails_cum_global[-1]}', color='green', linewidth=2)
plt.title('Aggregated Cumulative Coin Toss Results: All Coins')
plt.xlabel('Number of Total Tosses')
plt.ylabel('Cumulative Count')
plt.legend()
plt.grid(True)
plt.show()

# --- 4. SUMMARY TABLE ---
print("\n" + "="*45)
print(f"{'COIN':<8} | {'HEADS':<7} | {'TAILS':<7} | {'% HEADS':<8}")
print("-" * 45)
for coin, content in raw_data.items():
    h_flat = [toss for group in content["heads_groups"] for toss in sublist]
    t_flat = [toss for group in content["tails_groups"] for toss in sublist]
    h_total = sum(h_flat)
    t_total = sum(t_flat)
    total_tosses = len(h_flat) + len(t_flat)
    perc = (h_total / total_tosses * 100) if total_tosses > 0 else 0
    print(f"{coin:<8} | {h_total:<7} | {t_total:<7} | {perc:>6.1f}%")
print("="*45)